import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import ProfessionalLoading from './components/ProfessionalLoading';

const CompleteUploadPage = () => {
  const navigate = useNavigate();
  const [files, setFiles] = useState([]);
  const [uploading, setUploading] = useState(false);
  const [error, setError] = useState('');
  const [dragOver, setDragOver] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);

  useEffect(() => {
    // Clear any existing data on mount
    localStorage.removeItem('companyData');
  }, []);

  const generateMockData = (uploadedFiles) => {
    const companies = uploadedFiles.map((file, index) => ({
      unique_hash: `company_${index}_${Date.now()}`,
      company: `Company ${index + 1}`,
      industry: ['Technology', 'Manufacturing', 'Healthcare', 'Finance', 'Retail'][index % 5],
      revenue: `${(Math.random() * 900 + 100).toFixed(1)}M`,
      employees: Math.floor(Math.random() * 10000 + 100),
      founded: Math.floor(Math.random() * 50 + 1970),
      ai_analysis: {
        risk_analysis: {
          risk_score: Math.floor(Math.random() * 40 + 30),
          risk_category: ['LOW', 'MEDIUM', 'HIGH'][Math.floor(Math.random() * 3)],
          factors: {
            financial_health: Math.floor(Math.random() * 40 + 60),
            market_position: Math.floor(Math.random() * 30 + 70),
            operational_efficiency: Math.floor(Math.random() * 20 + 80),
            debt_ratio: (Math.random() * 0.6 + 0.1).toFixed(2)
          }
        },
        decision_result: {
          decision: ['APPROVE', 'REVIEW', 'DECLINE'][Math.floor(Math.random() * 3)],
          confidence: Math.floor(Math.random() * 25 + 75),
          recommended_amount: `${(Math.random() * 900 + 100).toFixed(1)}M`,
          reasoning: `Based on comprehensive financial analysis and risk assessment`
        }
      }
    }));

    return {
      is_multi_company: uploadedFiles.length > 1,
      companies: uploadedFiles.length > 1 ? companies : companies[0],
      uploaded_files: uploadedFiles.map(f => f.name),
      analysis_timestamp: new Date().toISOString()
    };
  };

  const handleFileSelect = (e) => {
    const selectedFiles = Array.from(e.target.files);
    const validFiles = selectedFiles.filter(file => {
      if (file.type !== 'application/pdf') {
        setError(`Invalid file type: ${file.name}. Only PDF files are allowed.`);
        return false;
      }
      if (file.size > 10 * 1024 * 1024) {
        setError(`File too large: ${file.name}. Maximum size is 10MB.`);
        return false;
      }
      return true;
    });

    if (validFiles.length > 0) {
      setFiles(prevFiles => [...prevFiles, ...validFiles.map(file => ({
        id: Math.random().toString(36).substr(2, 9),
        file: file,
        name: file.name,
        size: (file.size / 1024 / 1024).toFixed(2) + 'MB'
      }))]);
      setError('');
    }
  };

  const handleDragOver = (e) => {
    e.preventDefault();
    setDragOver(true);
  };

  const handleDragLeave = (e) => {
    e.preventDefault();
    setDragOver(false);
  };

  const handleDrop = (e) => {
    e.preventDefault();
    setDragOver(false);

    const droppedFiles = Array.from(e.dataTransfer.files);
    const validFiles = droppedFiles.filter(file => {
      if (file.type !== 'application/pdf') {
        setError(`Invalid file type: ${file.name}. Only PDF files are allowed.`);
        return false;
      }
      if (file.size > 10 * 1024 * 1024) {
        setError(`File too large: ${file.name}. Maximum size is 10MB.`);
        return false;
      }
      return true;
    });

    if (validFiles.length > 0) {
      setFiles(prevFiles => [...prevFiles, ...validFiles.map(file => ({
        id: Math.random().toString(36).substr(2, 9),
        file: file,
        name: file.name,
        size: (file.size / 1024 / 1024).toFixed(2) + 'MB'
      }))]);
      setError('');
    }
  };

  const removeFile = (fileId) => {
    setFiles(prevFiles => prevFiles.filter(f => f.id !== fileId));
  };

  const handleUpload = async () => {
    if (files.length === 0) {
      setError('Please select at least one file to upload.');
      return;
    }

    setUploading(true);
    setError('');

    // Simulate upload progress
    for (let i = 0; i <= 100; i += 10) {
      setUploadProgress(i);
      await new Promise(resolve => setTimeout(resolve, 100));
    }

    try {
      const mockData = generateMockData(files.map(f => f.file));
      localStorage.setItem('companyData', JSON.stringify(mockData));
      navigate('/dashboard');
    } catch (error) {
      setError('Upload failed. Please try again.');
    } finally {
      setUploading(false);
      setUploadProgress(0);
    }
  };

  if (uploading) {
    return <ProfessionalLoading message="Analyzing documents..." fullScreen />;
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-900 via-purple-900 to-indigo-900 relative overflow-hidden">
      {/* Animated background elements */}
      <div className="absolute inset-0">
        <div className="absolute top-20 left-20 w-72 h-72 bg-purple-300 rounded-full mix-blend-multiply filter blur-xl opacity-20 animate-pulse"></div>
        <div className="absolute top-40 right-20 w-72 h-72 bg-blue-300 rounded-full mix-blend-multiply filter blur-xl opacity-20 animate-pulse animation-delay-2000"></div>
        <div className="absolute bottom-20 left-1/2 w-72 h-72 bg-indigo-300 rounded-full mix-blend-multiply filter blur-xl opacity-20 animate-pulse animation-delay-4000"></div>
      </div>

      <div className="relative z-10">
        {/* Hero Section */}
        <div className="text-center px-4 pt-16 pb-12">
          <div className="flex justify-center mb-6">
            <div className="relative">
              <div className="absolute inset-0 bg-gradient-to-r from-blue-400 to-purple-400 rounded-full blur-lg opacity-50 animate-pulse"></div>
              <div className="relative bg-gradient-to-r from-blue-500 to-purple-500 p-4 rounded-full">
                <svg className="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9.75 17L9 20l-1 1h8l-1-1-.75-3M3 13h18M5 17h14a2 2 0 002-2V5a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z" />
                </svg>
              </div>
            </div>
          </div>

          <h1 className="text-5xl md:text-6xl font-bold text-white mb-6 bg-clip-text text-transparent bg-gradient-to-r from-blue-200 to-purple-200">
            AI Credit Decisioning Engine
          </h1>

          <p className="text-xl text-blue-100 max-w-3xl mx-auto mb-8 leading-relaxed">
            Upload company financial documents and generate AI-powered credit risk insights for smarter lending decisions.
          </p>

          <button className="bg-gradient-to-r from-blue-500 to-purple-600 text-white px-8 py-4 rounded-full font-semibold text-lg hover:from-blue-600 hover:to-purple-700 transform hover:scale-105 transition-all duration-300 shadow-xl hover:shadow-2xl">
            Analyze Documents
          </button>
        </div>

        {/* Upload Section */}
        <div className="max-w-6xl mx-auto px-4 pb-16">
          <div className="bg-white/10 backdrop-blur-lg rounded-3xl p-8 shadow-2xl border border-white/20">
            <h2 className="text-3xl font-bold text-white mb-8 text-center">Upload Company Documents</h2>

            {/* Drag and Drop Area */}
            <div
              className={`border-3 border-dashed rounded-2xl p-12 text-center transition-all duration-300 cursor-pointer
                ${dragOver 
                  ? 'border-blue-400 bg-blue-500/10 scale-105' 
                  : 'border-gray-400 bg-white/5 hover:border-blue-300 hover:bg-white/10'
                }`}
              onClick={() => document.getElementById('fileInput').click()}
              onDragOver={handleDragOver}
              onDragLeave={handleDragLeave}
              onDrop={handleDrop}
            >
              <div className="flex flex-col items-center">
                <div className={`w-20 h-20 rounded-full flex items-center justify-center mb-6 transition-all duration-300
                  ${dragOver ? 'bg-blue-500 scale-110' : 'bg-gradient-to-r from-blue-400 to-purple-400'}`}>
                  <svg className="w-10 h-10 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" />
                  </svg>
                </div>

                <p className="text-xl text-white font-semibold mb-2">
                  {dragOver ? 'Release to upload files' : 'Drag and drop your documents here'}
                </p>
                <p className="text-gray-300 mb-4">or click to browse</p>

                <div className="text-sm text-gray-400">
                  Supported: PDF files up to 10MB
                </div>
              </div>

              <input
                id="fileInput"
                type="file"
                multiple
                accept=".pdf"
                onChange={handleFileSelect}
                className="hidden"
              />
            </div>

            {/* Supported Documents */}
            <div className="mt-8 text-center">
              <h3 className="text-lg font-semibold text-white mb-4">Supported Documents:</h3>
              <div className="flex flex-wrap justify-center gap-3">
                {['Annual Reports (PDF)', 'Bank Statements', 'GST Returns', 'Balance Sheets', 'Loan Documents'].map((doc, index) => (
                  <span key={index} className="bg-white/10 text-white px-4 py-2 rounded-full text-sm border border-white/20">
                    {doc}
                  </span>
                ))}
              </div>
            </div>

            {/* Error Alert */}
            {error && (
              <div className="mt-6 bg-red-500/20 border border-red-500/50 rounded-xl p-4 flex items-center gap-3">
                <svg className="w-5 h-5 text-red-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                </svg>
                <p className="text-red-300 text-sm">{error}</p>
              </div>
            )}

            {/* File List */}
            {files.length > 0 && (
              <div className="mt-8">
                <h3 className="text-lg font-semibold text-white mb-4">Uploaded Files ({files.length})</h3>
                <div className="space-y-3">
                  {files.map((file, index) => (
                    <div key={file.id} className="bg-white/10 rounded-xl p-4 flex items-center justify-between border border-white/20 hover:bg-white/15 transition-all duration-300">
                      <div className="flex items-center gap-3">
                        <div className="w-10 h-10 bg-gradient-to-r from-blue-400 to-purple-400 rounded-lg flex items-center justify-center">
                          <svg className="w-5 h-5 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                          </svg>
                        </div>
                        <div>
                          <p className="text-white font-medium">{file.name}</p>
                          <p className="text-gray-400 text-sm">{file.size}</p>
                        </div>
                      </div>
                      <button
                        onClick={() => removeFile(file.id)}
                        className="text-red-400 hover:text-red-300 transition-colors duration-200"
                      >
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                        </svg>
                      </button>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {/* Upload Progress */}
            {uploading && (
              <div className="mt-8">
                <div className="flex justify-between text-sm text-white mb-2">
                  <span>Uploading and analyzing...</span>
                  <span>{uploadProgress}%</span>
                </div>
                <div className="w-full bg-white/20 rounded-full h-2">
                  <div 
                    className="bg-gradient-to-r from-blue-400 to-purple-400 h-2 rounded-full transition-all duration-300"
                    style={{ width: `${uploadProgress}%` }}
                  ></div>
                </div>
              </div>
            )}

            {/* Upload Button */}
            <div className="mt-8 text-center">
              <button
                onClick={handleUpload}
                disabled={files.length === 0 || uploading}
                className={`px-8 py-4 rounded-full font-semibold text-lg transition-all duration-300 transform
                  ${files.length === 0 || uploading
                    ? 'bg-gray-500 text-gray-300 cursor-not-allowed'
                    : 'bg-gradient-to-r from-blue-500 to-purple-600 text-white hover:from-blue-600 hover:to-purple-700 hover:scale-105 shadow-xl hover:shadow-2xl'
                  }`}
              >
                {uploading ? 'Processing...' : `Analyze ${files.length} Document${files.length !== 1 ? 's' : ''}`}
              </button>
            </div>
          </div>
        </div>

        {/* AI Feature Highlights */}
        <div className="max-w-6xl mx-auto px-4 pb-16">
          <h2 className="text-3xl font-bold text-white text-center mb-12">AI-Powered Features</h2>
          <div className="grid md:grid-cols-3 gap-8">
            {/* Feature 1 */}
            <div className="bg-white/10 backdrop-blur-lg rounded-2xl p-6 border border-white/20 hover:bg-white/15 transform hover:scale-105 transition-all duration-300 hover:shadow-2xl">
              <div className="w-16 h-16 bg-gradient-to-r from-blue-400 to-blue-600 rounded-xl flex items-center justify-center mb-4">
                <svg className="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" />
                </svg>
              </div>
              <h3 className="text-xl font-bold text-white mb-3">AI Credit Risk Analysis</h3>
              <p className="text-gray-300">Automatically analyze financial documents to estimate company creditworthiness with advanced machine learning algorithms.</p>
            </div>

            {/* Feature 2 */}
            <div className="bg-white/10 backdrop-blur-lg rounded-2xl p-6 border border-white/20 hover:bg-white/15 transform hover:scale-105 transition-all duration-300 hover:shadow-2xl">
              <div className="w-16 h-16 bg-gradient-to-r from-purple-400 to-purple-600 rounded-xl flex items-center justify-center mb-4">
                <svg className="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" />
                </svg>
              </div>
              <h3 className="text-xl font-bold text-white mb-3">Financial Pattern Detection</h3>
              <p className="text-gray-300">Identify revenue trends, liabilities, and financial risks through sophisticated pattern recognition and anomaly detection.</p>
            </div>

            {/* Feature 3 */}
            <div className="bg-white/10 backdrop-blur-lg rounded-2xl p-6 border border-white/20 hover:bg-white/15 transform hover:scale-105 transition-all duration-300 hover:shadow-2xl">
              <div className="w-16 h-16 bg-gradient-to-r from-indigo-400 to-indigo-600 rounded-xl flex items-center justify-center mb-4">
                <svg className="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9.663 17h4.673M12 3v1m6.364 1.636l-.707.707M21 12h-1M4 12H3m3.343-5.657l-.707-.707m2.828 9.9a5 5 0 117.072 0l-.548.547A3.374 3.374 0 0014 18.469V19a2 2 0 11-4 0v-.531c0-.895-.356-1.754-.988-2.386l-.548-.547z" />
                </svg>
              </div>
              <h3 className="text-xl font-bold text-white mb-3">Explainable AI Insights</h3>
              <p className="text-gray-300">Provide transparent reasoning for credit decisions with detailed explanations and confidence scores for each recommendation.</p>
            </div>
          </div>
        </div>

        {/* How It Works Section */}
        <div className="max-w-6xl mx-auto px-4 pb-16">
          <h2 className="text-3xl font-bold text-white text-center mb-12">How It Works</h2>
          <div className="grid md:grid-cols-3 gap-8">
            {/* Step 1 */}
            <div className="text-center">
              <div className="w-20 h-20 bg-gradient-to-r from-blue-400 to-blue-600 rounded-full flex items-center justify-center mx-auto mb-4">
                <svg className="w-10 h-10 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" />
                </svg>
              </div>
              <h3 className="text-xl font-bold text-white mb-2">Step 1</h3>
              <p className="text-2xl font-bold text-blue-300 mb-3">Upload Documents</p>
              <p className="text-gray-300">Drag and drop your financial documents in PDF format</p>
            </div>

            {/* Step 2 */}
            <div className="text-center">
              <div className="w-20 h-20 bg-gradient-to-r from-purple-400 to-purple-600 rounded-full flex items-center justify-center mx-auto mb-4">
                <svg className="w-10 h-10 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                </svg>
              </div>
              <h3 className="text-xl font-bold text-white mb-2">Step 2</h3>
              <p className="text-2xl font-bold text-purple-300 mb-3">AI Extracts Financial Data</p>
              <p className="text-gray-300">Our AI analyzes and extracts key financial metrics</p>
            </div>

            {/* Step 3 */}
            <div className="text-center">
              <div className="w-20 h-20 bg-gradient-to-r from-indigo-400 to-indigo-600 rounded-full flex items-center justify-center mx-auto mb-4">
                <svg className="w-10 h-10 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 17v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" />
                </svg>
              </div>
              <h3 className="text-xl font-bold text-white mb-2">Step 3</h3>
              <p className="text-2xl font-bold text-indigo-300 mb-3">Generate Credit Risk Report</p>
              <p className="text-gray-300">Receive comprehensive credit analysis and recommendations</p>
            </div>
          </div>
        </div>

        {/* Footer */}
        <footer className="bg-black/20 backdrop-blur-lg border-t border-white/10">
          <div className="max-w-6xl mx-auto px-4 py-8">
            <div className="flex flex-col md:flex-row justify-between items-center">
              <div className="text-center md:text-left mb-4 md:mb-0">
                <h3 className="text-xl font-bold text-white mb-2">AI Credit Decisioning Engine</h3>
                <p className="text-gray-400">Built for smarter financial risk assessment.</p>
              </div>
              <div className="flex gap-6">
                <a href="#" className="text-gray-400 hover:text-white transition-colors duration-200">Dashboard</a>
                <a href="#" className="text-gray-400 hover:text-white transition-colors duration-200">Upload</a>
                <a href="#" className="text-gray-400 hover:text-white transition-colors duration-200">Reports</a>
              </div>
            </div>
          </div>
        </footer>
      </div>
    </div>
  );
};

export default CompleteUploadPage;
